import java.util.*;

class PaginationOffset {
    static String paginationOffset(int[] values) {
        Integer[] copy = Arrays.stream(values).boxed().toArray(Integer[]::new);
        Arrays.sort(copy, Collections.reverseOrder());
        return Arrays.stream(copy).limit(3).map(String::valueOf).reduce((a, b) -> a + "," + b).orElse("");
    }
}
